 */
export function spawnPlayer(world, x, y) {
  const id = world.create();
  world.add(id, Position, { x, y });
  world.add(id, Velocity, { vx: 0, vy: 0 });
  world.add(id, Facing,   { angle: 0 });
  world.add(id, Collider, { radius: 14 });
