// display/renderer.js
// Main frame renderer — queries ECS world, draws everything.
// No simulation logic. Pure display.

import { Position, Velocity, Collider, Facing, Health, Actor, ActorKind, Projectile, PointLight, Input, GroundItem, ItemInfo } from '../rules/components/index.js';
import { AI } from '../rules/components/index.js';
import { applyCamera } from './camera/controller.js';
import { Particle } from './passes/vfx/particles/particlePool.js';

/**
 * @param {object} deps
 * @param {HTMLCanvasElement} deps.canvas
 * @param {CanvasRenderingContext2D} deps.ctx
 * @param {object} deps.cam
 * @param {object} deps.caveBake
 * @param {object} deps.torchPass
 * @param {object} deps.fx — ParticleFX instance
 * @param {object} deps.world
 * @param {object} deps.hud — HUD DOM elements { hud, readL, readR, zoomReadout }
 * @param {object} deps.input — { leftStick, rightStick, keys, keyboardInput }
 * @param {number} deps.SEED
 * @param {object} deps.runtimeEvents
 */
export function createRenderer(deps) {
  const { canvas, ctx, cam, caveBake, torchPass, fx, world, hud, input, SEED, runtimeEvents, boltFx, net } = deps;
  let lastRenderTime = 0;

  return function renderFrame() {
    // Find local player via Input component query
    let playerId = null, inp = null, pos = null, col = null, fac = null;
    for (const [id, _inp, _pos, _col, _fac] of world.query(Input, Position, Collider, Facing)) {
      playerId = id; inp = _inp; pos = _pos; col = _col; fac = _fac;
      break;
    }
    if (!playerId) return; // no player
    const localPeerState = net?.getLocalPeer?.()?.state;
    if (Number.isFinite(localPeerState?.x) && Number.isFinite(localPeerState?.y)) {
      pos = {
        ...pos,
        x: localPeerState.x,
        y: localPeerState.y,
      };
      fac = {
        ...fac,
        angle: Number.isFinite(localPeerState.facing) ? localPeerState.facing : fac.angle,
      };
    }

    const kb = input.keyboardInput();

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0b0f12';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    applyCamera(ctx, cam, canvas);
    ctx.drawImage(caveBake.canvas, 0, 0);
    const useServerEntities = Boolean(net?.hasServerEntities?.());

    // Draw ground items (potions etc)
    for (const [id, ipos, gi, info] of world.query(Position, GroundItem, ItemInfo)) {
      const t = performance.now() * 0.003;
      const bob = Math.sin(t + id * 2) * 2;  // gentle bob
      ctx.fillStyle = '#ff5080';
      ctx.font = 'bold 18px ui-monospace, monospace';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(info.glyph, ipos.x, ipos.y + bob);
    }

    // Draw player
    ctx.beginPath();
    ctx.arc(pos.x, pos.y, col.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#193447';
    ctx.fill();
    ctx.strokeStyle = '#6fd';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = '#cfe8ff';
    ctx.font = `bold ${Math.floor(col.radius * 1.4)}px ui-monospace, monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('@', pos.x, pos.y + 1);

    // Torch glyph offset from player
    ctx.fillStyle = '#ffbe60';
    ctx.font = 'bold 14px ui-monospace, monospace';
    ctx.fillText('\u2020', pos.x + col.radius + 4, pos.y - col.radius + 2);

    // Draw remote players from the latest network snapshot.
    if (net) {
      for (const peer of net.getRemotePeers()) {
        const rpos = peer.state;
        if (!Number.isFinite(rpos?.x) || !Number.isFinite(rpos?.y)) continue;

        ctx.beginPath();
        ctx.arc(rpos.x, rpos.y, col.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(30,80,120,0.72)';
        ctx.fill();
        ctx.strokeStyle = 'rgba(130,220,255,0.9)';
        ctx.lineWidth = 2;
        ctx.stroke();

        ctx.fillStyle = 'rgba(215,245,255,0.95)';
        ctx.font = `bold ${Math.floor(col.radius * 1.4)}px ui-monospace, monospace`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('@', rpos.x, rpos.y + 1);

        const angle = Number.isFinite(rpos.facing) ? rpos.facing : 0;
        const aimLen = col.radius + 12;
        ctx.beginPath();
        ctx.moveTo(rpos.x + Math.cos(angle) * col.radius, rpos.y + Math.sin(angle) * col.radius);
        ctx.lineTo(rpos.x + Math.cos(angle) * aimLen, rpos.y + Math.sin(angle) * aimLen);
        ctx.strokeStyle = 'rgba(140,245,255,0.85)';
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.stroke();
      }
    }

    if (useServerEntities) {
      for (const mob of net.getEntities('mobs')) {
        drawNetMob(ctx, mob);
      }
    }

    // Draw mobs
    if (!useServerEntities) {
      for (const [id, mpos, mcol, actor, mfac] of world.query(Position, Collider, Actor, Facing)) {
        if (actor.kind !== ActorKind.MOB) continue;
        drawMob(ctx, mpos.x, mpos.y, mcol.radius, mfac.angle, actor.glyph);
      }
    }

    if (useServerEntities) {
      for (const projectile of net.getEntities('projectiles')) {
        drawNetProjectile(ctx, projectile);
        spawnNetProjectileTrail(fx, projectile);
      }
    }

    // Draw projectiles
    if (!useServerEntities) {
      for (const [id, bpos, vel, proj, bcol] of world.query(Position, Velocity, Projectile, Collider)) {
        const isEnemy = world.has(proj.owner, AI);
        drawProjectile(ctx, bpos.x, bpos.y, vel.vx, vel.vy, bcol.radius, proj.trailColor, isEnemy);
      }
    }

    // Health bars
    for (const [id, hpos, hcol, hp] of world.query(Position, Collider, Health)) {
      if (hp.hp >= hp.maxHp && id !== playerId) continue;
      const ratio = Math.max(0, hp.hp / Math.max(1, hp.maxHp));
      const barW = hcol.radius * 2.2;
      const barH = 4;
      const bx = hpos.x - barW * 0.5;
      const by = hpos.y - hcol.radius - 10;
      const hue = Math.round(120 * ratio);

      ctx.fillStyle = 'rgba(10,12,18,0.8)';
      ctx.fillRect(bx, by, barW, barH);
      if (ratio > 0) {
        ctx.fillStyle = `hsl(${hue} 85% 48%)`;
        ctx.fillRect(bx + 0.5, by + 0.5, (barW - 1) * ratio, barH - 1);
      }
      ctx.strokeStyle = 'rgba(0,0,0,0.85)';
      ctx.lineWidth = 0.5;
      ctx.strokeRect(bx, by, barW, barH);
    }

    // Player aim indicator
    const aimLen = col.radius + 14;
    ctx.beginPath();
    ctx.moveTo(pos.x + Math.cos(fac.angle) * col.radius, pos.y + Math.sin(fac.angle) * col.radius);
    ctx.lineTo(pos.x + Math.cos(fac.angle) * aimLen, pos.y + Math.sin(fac.angle) * aimLen);
    ctx.strokeStyle = '#8fe';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Lightning bolt FX (world space, additive)
    const now = performance.now() * 0.001;
    const renderDt = lastRenderTime > 0 ? now - lastRenderTime : 0.016;
    lastRenderTime = now;
    if (boltFx) boltFx.render(ctx, renderDt);
    if (useServerEntities) {
      for (const event of net.drainEvents()) {
        handleNetEvent(fx, event);
      }
    }

    // Torch lighting pass — cap projectile lights for perf
    const lights = [];
    const MAX_PROJ_LIGHTS = 6;
    let projLightCount = 0;
    const t = now;

    for (const [id, lpos, pl] of world.query(Position, PointLight)) {
      if (!pl.enabled) continue;

      // Skip excess projectile lights (small radius = projectile)
      const isProjectileLight = pl.radius <= 130;
      if (isProjectileLight) {
        if (++projLightCount > MAX_PROJ_LIGHTS) continue;
      }

      const isTorch = pl.b < pl.r;
      if (isTorch) {
        const flicker = 1.0
          + 0.12 * Math.sin(t * 5.7 + id)
          + 0.08 * Math.sin(t * 13.3 + id)
          + 0.06 * Math.sin(t * 23.1)
          + 0.10 * (Math.random() - 0.5);
        lights.push({
          x: lpos.x, y: lpos.y,
          radius: pl.radius * Math.max(0.7, flicker),
          color: [
            Math.min(255, pl.r * Math.max(0.8, flicker)),
            Math.min(255, pl.g * Math.max(0.6, flicker * 0.85)),
            Math.min(255, pl.b * Math.max(0.3, flicker * 0.5)),
          ],
        });
      } else {
        const shimmer = 1.0 + 0.05 * Math.sin(t * 20 + id * 7);
        lights.push({
          x: lpos.x, y: lpos.y,
          radius: pl.radius * shimmer,
          color: [pl.r * shimmer, pl.g * shimmer, pl.b],
        });
      }
    }
    if (useServerEntities) {
      for (const projectile of net.getEntities('projectiles')) {
        lights.push({
          x: projectile.x,
          y: projectile.y,
          radius: 120,
          color: [140, 200, 255],
        });
      }
    }
    torchPass.render(ctx, lights, canvas.width, canvas.height, cam);

    // Particles
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    fx.ctx = ctx;
    fx.render({ mode: 'lighter' });

    // Float text (world space, after particles but before HUD)
    if (deps.floatText) {
      deps.floatText.stepAuto();
      applyCamera(ctx, cam, canvas);
      deps.floatText.render(ctx);
      ctx.setTransform(1, 0, 0, 1, 0, 0);
    }

    // Player death overlay
    const playerHp = world.get(playerId, Health);
    if (playerHp.hp <= 0) {
      ctx.fillStyle = 'rgba(80,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff4444';
      ctx.font = 'bold 48px Inter, system-ui, sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('YOU DIED', canvas.width / 2, canvas.height / 2 - 20);
      ctx.fillStyle = '#ccc';
      ctx.font = '20px Inter, system-ui, sans-serif';
      ctx.fillText('refresh to respawn', canvas.width / 2, canvas.height / 2 + 30);
    }

    // HUD
    const hpText = playerHp.hp > 0 ? `  HP:${playerHp.hp}/${playerHp.maxHp}` : '';
    const netText = net ? '  ' + net.getStatusText() : '';
    hud.hud.textContent = 'Hack Arena  seed:' + SEED.toString(16) + hpText + '  casts:' + runtimeEvents.casts + netText;
    hud.zoomReadout.textContent = `zoom: ${cam.scale.toFixed(2)}x  [+/- or scroll]`;
    const routerOut = input.leftStick.getOutput();
    hud.readL.textContent = routerOut.left.active
      ? `L x:${inp.moveX.toFixed(2)} y:${inp.moveY.toFixed(2)}`
      : (Math.abs(kb.mx) + Math.abs(kb.my) > 0 ? `KB ${kb.mx},${kb.my}` : 'L stick idle');
    hud.readR.textContent = routerOut.right.active
      ? `R x:${inp.aimX.toFixed(2)} y:${inp.aimY.toFixed(2)}`
      : 'R stick idle';
  };
}

function drawNetMob(ctx, mob) {
  if (!Number.isFinite(mob?.x) || !Number.isFinite(mob?.y)) return;
  drawMob(ctx, mob.x, mob.y, mob.radius || 12, mob.facing || 0, mob.glyph || 'W');
}

function drawMob(ctx, x, y, radius, facing, glyph) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = '#2a1540';
  ctx.fill();
  ctx.strokeStyle = '#a050ff';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = '#d0a0ff';
  ctx.font = `bold ${Math.floor(radius * 1.4)}px ui-monospace, monospace`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const aimLen = radius + 10;
  ctx.beginPath();
  ctx.moveTo(x + Math.cos(facing) * radius, y + Math.sin(facing) * radius);
  ctx.lineTo(x + Math.cos(facing) * aimLen, y + Math.sin(facing) * aimLen);
  ctx.strokeStyle = '#c070ff';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.stroke();

  ctx.fillStyle = '#f1d8ff';
  ctx.font = `bold ${Math.max(16, Math.floor(radius * 1.6))}px ui-monospace, monospace`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(glyph, x, y + 1);
}

function drawNetProjectile(ctx, projectile) {
  if (!Number.isFinite(projectile?.x) || !Number.isFinite(projectile?.y)) return;
  drawProjectile(
    ctx,
    projectile.x,
    projectile.y,
    projectile.vx || 0,
    projectile.vy || 0,
    projectile.radius || 5,
    projectile.trailColor,
    false,
  );
}

function drawProjectile(ctx, x, y, vx, vy, radius, trailColor, isEnemy) {
  const isArrow = trailColor === '#c8a050';

  if (isArrow) {
    const angle = Math.atan2(vy, vx);
    const len = 14;
    const tailX = x - Math.cos(angle) * len;
    const tailY = y - Math.sin(angle) * len;

    ctx.beginPath();
    ctx.moveTo(tailX, tailY);
    ctx.lineTo(x, y);
    ctx.strokeStyle = 'rgba(210,180,110,0.9)';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(x, y, 2.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(240,230,200,0.95)';
    ctx.fill();

    const fLen = 4;
    const pnx = -Math.sin(angle);
    const pny = Math.cos(angle);
    ctx.beginPath();
    ctx.moveTo(tailX + pnx * fLen, tailY + pny * fLen);
    ctx.lineTo(tailX - pnx * fLen, tailY - pny * fLen);
    ctx.strokeStyle = 'rgba(180,160,120,0.6)';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    return;
  }

  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = isEnemy ? 'rgba(180,80,255,0.9)' : 'rgba(140,210,255,0.9)';
  ctx.fill();
  ctx.fillStyle = isEnemy ? '#e0b0ff' : '#e0f4ff';
  ctx.font = 'bold 10px ui-monospace, monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(isEnemy ? '\u2726' : '\u2744', x, y);
}

function spawnNetProjectileTrail(fx, projectile) {
  if (!fx?.pool || !Number.isFinite(projectile?.x) || !Number.isFinite(projectile?.y)) return;
  const rgb = hexRgb(projectile.trailColor || '#8cd8ff');
  const angle = Math.atan2(projectile.vy || 0, projectile.vx || 0) + Math.PI;
  for (let i = 0; i < 2; i++) {
    const spread = (Math.random() - 0.5) * 0.8;
    const speed = 12 + Math.random() * 28;
    fx.pool.spawn(new Particle({
      x: projectile.x,
      y: projectile.y,
      vx: Math.cos(angle + spread) * speed,
      vy: Math.sin(angle + spread) * speed,
      ax: 0,
      ay: 0,
      life: 0.18 + Math.random() * 0.16,
      size0: 3,
      size1: 0.5,
      r: rgb.r,
      g: rgb.g,
      b: rgb.b,
      a0: 0.8,
      a1: 0,
    }));
  }
}

function handleNetEvent(fx, event) {
  if (!fx?.pool || !Number.isFinite(event?.x) || !Number.isFinite(event?.y)) return;
  if (event.type === 'projectile.destroyed') {
    spawnBurst(fx, event.x, event.y, event.color || '#b0e0ff', 12, 45);
  } else if (event.type === 'mob.died') {
    spawnBurst(fx, event.x, event.y, '#d0a0ff', 22, 75);
  }
}

function spawnBurst(fx, x, y, color, count, speedBase) {
  const rgb = hexRgb(color);
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = speedBase * (0.45 + Math.random() * 0.75);
