import { assert, assertAlmostEquals } from "https://deno.land/std@0.220.0/assert/mod.ts";
import { generateCave, CaveProfile } from '../public/src/rules/geometry/caveGen.js';
import { createArenaSimWorld } from '../public/src/rules/sim/arenaSim.js';

Deno.test("arena sim: player movement uses shared movement system", () => {
  const cave = generateCave({
    seed: 1234,
    width: 1000,
    height: 1000,
    profile: CaveProfile.CAVERNS,
    spawnCount: 1,
  });
  const sim = createArenaSimWorld({
    seed: 1234,
    grid: cave.grid,
    spawns: cave.spawns,
  });

  sim.addPlayer('peer-a', 0);
  const before = sim.getPlayerSnapshot('peer-a').state;
  sim.setPlayerInput('peer-a', {
    moveX: 1,
    moveY: 0,
    aimX: 1,
    aimY: 0,
    fire: false,
  });
  sim.step(0.25);

  const after = sim.getPlayerSnapshot('peer-a').state;
  assert(after.x > before.x);
  assertAlmostEquals(after.y, before.y, 1);
  assertAlmostEquals(after.facing, 0, 1e-6);
});

